/* ============================================================
   PATCH v1.5.1 — привязка отметок к гипотезам/заданиям
   ============================================================ */

/* Селект в модалке отметки */
#logHypGroup > label {
    display: block !important;
    font-size: 0.73rem !important;
    margin-bottom: 4px !important;
    font-weight: 700 !important;
    color: var(--trk-meta) !important;
    text-transform: uppercase !important;
    letter-spacing: 0.4px !important;
}
#log_hyp_item {
    width: 100% !important;
    box-sizing: border-box !important;
    padding: 8px 12px !important;
    border-radius: 10px !important;
    border: 1px solid var(--trk-input-border) !important;
    background: var(--trk-input-bg) !important;
    color: var(--trk-text) !important;
    font-family: inherit !important;
    font-size: 0.9rem !important;
}
#log_hyp_item:focus {
    outline: none !important;
    border-color: var(--trk-input-focus) !important;
}

/* «📝 Отметки о ходе работы» в дереве гипотез */
.hyp-progress-details {
    margin-top: 10px !important;
    border: 1px solid var(--trk-border-soft) !important;
    border-radius: 8px !important;
    background: rgba(0,0,0,0.06) !important;
    padding: 0 !important;
    overflow: hidden !important;
}
.hyp-progress-details > summary.hyp-progress-label {
    padding: 8px 14px !important;
    cursor: pointer !important;
    display: flex !important;
    align-items: center !important;
    list-style: none !important;
    font-size: 0.8rem !important;
    font-weight: 700 !important;
    color: var(--trk-text) !important;
    margin: 0 !important;
    text-transform: none !important;
    letter-spacing: 0 !important;
}
.hyp-progress-details > summary::-webkit-details-marker { display: none !important; }
.hyp-progress-details > summary::before {
    content: '▶' !important;
    font-size: 0.65em !important;
    margin-right: 8px !important;
    color: #6dc2f0 !important;
    transition: transform 0.2s !important;
    display: inline-block !important;
}
.hyp-progress-details[open] > summary::before { transform: rotate(90deg) !important; }
.hyp-progress-count {
    margin-left: auto !important;
    background: rgba(109,194,240,0.20) !important;
    color: #6dc2f0 !important;
    padding: 1px 8px !important;
    border-radius: 10px !important;
    font-size: 0.7rem !important;
    font-weight: 800 !important;
    min-width: 20px !important;
    text-align: center !important;
}
.hyp-progress-empty {
    padding: 10px 14px !important;
    font-size: 0.8rem !important;
    color: var(--trk-meta) !important;
    font-style: italic !important;
}
.hyp-progress-list {
    border-top: 1px dashed var(--trk-border-soft) !important;
    padding: 8px 12px !important;
    display: flex !important;
    flex-direction: column !important;
    gap: 6px !important;
    max-height: 240px !important;
    overflow-y: auto !important;
}
.hyp-progress-item {
    display: flex !important;
    gap: 10px !important;
    align-items: flex-start !important;
    padding: 6px 8px !important;
    background: var(--trk-input-bg) !important;
    border-radius: 8px !important;
    border-left: 3px solid #6dc2f0 !important;
}
.hyp-progress-avatar {
    width: 26px !important;
    height: 26px !important;
    border-radius: 50% !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    color: #fff !important;
    font-size: 0.62rem !important;
    font-weight: 800 !important;
    flex: 0 0 auto !important;
    text-shadow: 0 1px 2px rgba(0,0,0,0.35) !important;
}
.hyp-progress-body { flex: 1 !important; min-width: 0 !important; }
.hyp-progress-line1 {
    display: flex !important;
    gap: 8px !important;
    align-items: baseline !important;
    flex-wrap: wrap !important;
    font-size: 0.8rem !important;
}
.hyp-progress-line1 b { color: var(--trk-text) !important; }
.hyp-progress-date {
    color: var(--trk-meta) !important;
    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace !important;
    font-size: 0.72rem !important;
}
.hyp-progress-st {
    margin-left: auto !important;
    padding: 1px 8px !important;
    border-radius: 8px !important;
    background: rgba(109,194,240,0.15) !important;
    color: #6dc2f0 !important;
    font-size: 0.7rem !important;
    font-weight: 700 !important;
}
.hyp-progress-comment {
    font-size: 0.8rem !important;
    color: var(--trk-desc) !important;
    margin-top: 4px !important;
    white-space: pre-wrap !important;
    word-break: break-word !important;
    line-height: 1.4 !important;
}

/* Светлая тема */
body.trk-theme-light .hyp-progress-details { background: #f7f9fa !important; }
body.trk-theme-light .hyp-progress-details > summary.hyp-progress-label { color: #212121 !important; }
body.trk-theme-light .hyp-progress-item { background: #ffffff !important; }

function _progressNotesHtml(item) {
    // PATCH v1.5.1: список отметок о ходе работы для гипотезы/задания
    var taskIdEl = document.getElementById('task_id');
    var taskId = taskIdEl ? taskIdEl.value : '';
    if (!taskId || !item || !item.id) return '';
    var st = window.__trkState || {};
    var logs = (st.log || []).filter(function(l){
        return l && l.task_id === taskId && l.hyp_item_id === item.id;
    });
    if (!logs.length) {
        return '<details class="hyp-progress-details"><summary class="hyp-progress-label">📝 Отметки о ходе работы <span class="hyp-progress-count">0</span></summary><div class="hyp-progress-empty">Пока нет отметок по этой гипотезе/заданию</div></details>';
    }
    logs.sort(function(a, b){ return String(b.date || '').localeCompare(String(a.date || '')); });
    var emps = st.employees || [];
    function _einit(name){
        var p = String(name || '').trim().split(/\\s+/);
        if (!p.length) return '?';
        if (p.length === 1) return p[0].slice(0, 2).toUpperCase();
        return ((p[0][0] || '') + (p[1][0] || '')).toUpperCase();
    }
    function _stIcon(s){
        return s === 'done' ? '✅' : (s === 'in_progress' ? '🔵' : (s === 'blocked' ? '🔴' : '📝'));
    }
    var html = '<div class="hyp-progress-list">';
    logs.forEach(function(l){
        var e = null;
        for (var i = 0; i < emps.length; i++) if (emps[i].id === l.employee_id) { e = emps[i]; break; }
        var empName = e ? (e.name || l.employee_id) : l.employee_id;
        var color = e ? (e.color || '#888') : '#888';
        html += '<div class="hyp-progress-item">'
             +   '<span class="hyp-progress-avatar" style="background:' + esc(color) + ';">' + esc(_einit(empName)) + '</span>'
             +   '<div class="hyp-progress-body">'
             +     '<div class="hyp-progress-line1">'
             +       '<b>' + esc(empName) + '</b>'
             +       '<span class="hyp-progress-date">' + esc(l.date || '') + '</span>'
             +       '<span class="hyp-progress-st">' + _stIcon(l.status) + ' ' + esc(String(l.hours || 0)) + ' ч</span>'
             +     '</div>'
             +     (l.comment ? '<div class="hyp-progress-comment">' + esc(l.comment) + '</div>' : '')
             +   '</div></div>';
    });
    html += '</div>';
    return '<details class="hyp-progress-details"><summary class="hyp-progress-label">📝 Отметки о ходе работы <span class="hyp-progress-count">' + logs.length + '</span></summary>' + html + '</details>';
}
